{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목을 실행 계획·로그·호출 구조 등의 근거로 진단하고, 원인에 맞는 개선을 적용한 뒤 전후 성능을 수치로 검증할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회가 느렸던 상황과 당시 쿼리 구조, 조회 조건, 데이터 규모 등 성능 문제의 맥락을 설명한다.",
          "task": "신고 목록 조회 지연의 원인을 파악하고, 개선 효과를 비교할 측정 대상과 조건을 정하는 과제를 설명한다.",
          "action": "실행 계획·로그·호출 구조에서 확인한 병목 근거를 제시하고, 인덱스 추가와 조인 정리가 해당 원인을 어떻게 해소했는지 본인의 조치와 연결해 설명한다.",
          "result": "조회 시간이 3.2초에서 0.4초로 줄었다는 결과를 측정 방법 및 비교 조건과 함께 설명하여 개선 효과를 뒷받침한다."
        },
        "expectedEvidence": [
          "실행 계획·로그·호출 구조 등에서 확인한 구체적인 병목 징후와 원인 판단의 연결",
          "조회 조건과 조인 구조를 고려한 인덱스·쿼리 변경 내용 및 선택 이유",
          "진단한 원인과 실제 적용한 개선 조치 사이의 인과관계",
          "개선 전후 응답 시간 수치와 측정 방법, 비교 조건의 일관성"
        ]
      },
      "question": "포켓마켓 인턴 당시 신고 목록 조회를 3.2초에서 0.4초로 줄인 경험에서, 병목 진단부터 개선 효과 검증까지 어떻게 진행했는지 말씀해 주세요.",
      "answerTip": "당시 경험을 본인의 말로 차분히 설명하세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "조회 지연 상황과 실행 계획·로그·호출 구조에서 발견한 구체적 근거를 연결하여 병목 원인을 설명한다.",
            "인덱스와 조인 변경 내용을 구체적으로 설명하고, 해당 조치가 진단한 병목을 해소하는 이유를 제시한다.",
            "3.2초와 0.4초의 측정 방법 및 비교 조건을 설명하여 개선 전후 수치의 비교 타당성을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목을 판단한 근거와 인덱스·조인 개선 조치는 제시하지만, 실행 계획 해석이나 원인과 조치의 연결이 일부 불명확하다.",
            "개선 전후 수치는 제시하지만 측정 방법이나 비교 조건에 대한 설명이 부족하여 효과 검증의 구체성이 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스 추가나 조인 수정 사실만 나열하고 병목을 판단한 근거 또는 조치의 이유를 설명하지 못한다.",
            "개선 전후 수치를 제시하지 못하거나, 수치를 언급하더라도 실제 측정에 근거한 결과인지 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류를 로그와 모니터링 지표로 추적해 원인을 좁히고, 당장의 복구와 장기적인 재발 방지를 구분하여 실행할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 다음 날 알림이 중복 발송된다는 문의가 들어온 상황과 오류가 발생한 서버 운영 환경을 설명한다.",
          "task": "중복 발송의 원인을 확인하고 오류를 중단시키는 당면 과제와, 같은 문제가 반복되지 않도록 하는 과제를 구분한다.",
          "action": "시간순 로그와 당시 확인한 모니터링 지표 등을 통해 가설을 검증하고 두 서버의 스케줄러 동시 실행으로 원인을 좁힌 과정을 설명한다. 잠금 적용 등 복구 조치와 배포 체크리스트 보완 등 재발 방지 조치를 구분해 설명한다.",
          "result": "조치 후 로그와 지표 등에서 중복 발송이 해소되었는지 확인한 방법과, 재발 방지 조치가 적용되었는지 확인한 내용을 설명한다."
        },
        "expectedEvidence": [
          "오류 발생 시점과 실행 주체 등을 로그 및 모니터링 지표로 대조하여 현상을 추적하거나 재현한 과정",
          "초기 가설을 검증하고 스케줄러의 동시 실행으로 원인을 좁힌 근거",
          "당장의 중복 발송을 멈추기 위한 복구 조치와 해당 조치의 작동 원리",
          "복구와 구분되는 재발 방지 방안 및 확인된 원인과의 연결",
          "조치 후 중복 발송 해소와 재발 방지 조치 적용을 확인한 근거"
        ]
      },
      "question": "포켓마켓 인턴 당시 배포 후 알림 중복 발송 오류를 해결한 경험에서, 원인 추적부터 복구와 재발 방지까지 어떻게 진행했는지 말씀해 주세요.",
      "answerTip": "당시 경험을 본인의 말로 차분히 설명하세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그와 모니터링 지표 등 실제 확인한 관측 근거를 활용하여 오류를 추적하고, 초기 가설에서 스케줄러 동시 실행으로 원인을 좁힌 과정을 구체적으로 설명한다.",
            "잠금 적용 등 복구 조치가 중복 실행을 막는 원리를 설명하고, 체크리스트 보완 등 재발 방지 조치를 복구와 구분하여 원인에 연결한다.",
            "조치 후 중복 발송이 해소되었음을 확인한 근거와 재발 방지 조치의 적용 내용을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그나 지표에 근거한 원인 추적과 복구 조치는 확인되지만, 가설 검증 과정이나 관측 근거의 구체성이 부족하다.",
            "복구와 재발 방지 방안을 구분해 제시하지만, 조치의 작동 원리 또는 조치 이후 확인 결과에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "스케줄러 중복 실행이라는 결론만 언급하고 로그나 지표로 원인을 좁힌 근거를 설명하지 못한다.",
            "수정했다고만 답하거나, 당장의 복구와 재발 방지 방안을 구분하지 못하고 조치 이후 해소 여부도 확인하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 수집한 요청의 목적과 범위를 정리하고, 포함·제외 항목과 우선순위 및 예외 케이스를 요구사항 정의서에 구체화하여 개발·디자인 담당자와 구현 범위를 합의할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 여러 요청을 수집했으며, 서비스 구현을 위해 요청의 목적과 적용 범위를 명확히 해야 했던 상황",
          "task": "요청을 요구사항 정의서로 구체화하고 이번 구현에 포함하거나 제외할 범위를 담당자와 합의하는 본인의 역할",
          "action": "요청별 목적을 확인하고 포함·제외 항목, 우선순위, 예외 케이스를 문서화한 뒤 개발 담당자 등 구현 관계자와 검토하여 범위를 조정한 행동",
          "result": "최종 합의된 요구사항과 포함·제외 범위가 문서에 어떻게 반영되었는지 보여 주는 구체적인 결과"
        },
        "expectedEvidence": [
          "인터뷰에서 나온 실제 요청과 이를 통해 해결하려던 목적 및 적용 범위",
          "이번 구현의 포함·제외 항목과 그 구분 근거",
          "요구사항의 우선순위 및 판단 근거",
          "예외 케이스를 요구사항 정의서에 명시한 구체적인 내용",
          "개발·디자인 등 해당 구현 담당자와 범위를 검토하고 최종 합의 내용을 문서에 반영한 과정"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 인터뷰 요청을 요구사항 정의서로 정리하고 개발 담당자와 구현 범위를 합의한 과정을 설명해 주세요.",
      "answerTip": "본인이 맡은 사례를 중심으로 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 인터뷰 요청을 바탕으로 해결 목적과 적용 범위를 어떻게 정리했는지 구체적으로 설명한다.",
            "포함·제외 항목과 우선순위의 판단 근거를 제시하고, 예외 케이스를 요구사항으로 명시한 내용을 설명한다.",
            "본인이 구현 담당자와 범위를 검토·조정한 행동과 최종 합의된 내용이 요구사항 정의서에 반영된 결과를 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청의 목적과 범위를 정리해 요구사항 정의서를 작성한 본인의 행동은 확인된다.",
            "포함·제외 항목, 우선순위, 예외 케이스 중 일부는 설명하지만 나머지 내용이나 판단 근거가 부족하다.",
            "담당자와 범위를 논의한 사실은 확인되지만 구체적인 조정 과정이나 최종 문서 반영 결과가 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 수집하거나 나열한 사실만 설명하여 목적과 범위를 요구사항으로 구체화한 근거가 부족하다.",
            "포함·제외 항목, 우선순위, 예외 케이스를 정리한 구체적인 내용이 확인되지 않는다.",
            "담당자와 구현 범위를 합의한 과정과 본인의 행동이 확인되지 않거나 화면 표현 등 다른 주제에 머문다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예약 서비스의 기능 흐름을 화면 단위로 연결하고, 상태 변화와 예외 상황 및 안내 문구를 화면설계서에 명시하여 개발자와 디자이너가 구현할 수 있는 수준으로 구체화하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스에서 예약·취소·알림 기능의 흐름과 예외 상황을 화면설계서로 전달해야 했던 상황",
          "task": "선택한 기능의 화면 간 이동, 화면별 상태 변화, 예외 처리 및 안내 문구를 구현 가능한 수준으로 설계하는 본인의 역할",
          "action": "사용자 행동에 따른 화면 전환과 상태 변화 조건을 정의하고, 예외 발생 시 화면 처리와 안내 문구를 Figma 화면설계서에 구체적으로 명시한 행동",
          "result": "선택한 기능의 정상·예외 흐름과 화면별 표시 내용이 연결되어 개발자와 디자이너가 처리 방식을 파악할 수 있는 설계 결과"
        },
        "expectedEvidence": [
          "선택한 기능의 시작부터 완료까지 화면 단위로 연결된 흐름",
          "사용자 행동이나 처리 결과에 따른 화면별 상태 변화와 전환 조건",
          "구체적인 예외 상황과 해당 상황에서의 화면 처리 및 후속 흐름",
          "정상·예외 상태에서 사용자에게 표시할 실제 안내 문구 또는 그에 준하는 구체적인 문구 내용",
          "화면, 상태, 조건, 문구를 구현 담당자가 해석할 수 있도록 화면설계서에 표현한 방식"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 예약·취소·알림 중 한 흐름을 골라, 상태 변화와 예외 상황 및 안내 문구를 화면설계서에 구체화한 과정을 설명해 주세요.",
      "answerTip": "한 가지 사례를 차근차근 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "선택한 기능의 시작부터 완료까지 화면 간 흐름과 상태 변화 조건을 구체적으로 연결하여 설명한다.",
            "예외 상황별 화면 처리와 후속 흐름, 사용자에게 표시할 안내 문구를 구체적으로 제시한다.",
            "본인이 화면설계서에 화면·상태·조건·문구를 표현한 방식을 설명하며, 구현 담당자가 처리 방식을 파악할 수 있는 설계 결과가 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "선택한 기능의 화면 흐름과 이를 화면설계서로 작성한 본인의 행동은 확인된다.",
            "상태 변화, 예외 처리, 안내 문구 중 일부는 구체적이지만 나머지 내용이나 화면 간 연결 조건이 부족하다.",
            "화면설계서의 표현 방식은 설명하지만 구현 시 필요한 처리 조건이나 표시 내용 일부가 불명확하다."
          ]
        },
